1	// Live-mode orchestration: one request in, one typed { httpStatus, body } out.
2	// Order: validate, rate limit, reserve a run, check the kill switch (live
3	// codes only), then run in the mode the code is bound to. Fails closed. Never logs. Bodies carry fixed
4	// messages only: no keys, codes, upstream text, stack traces or company data.
5	
6	import type { LlmClient } from "../../core/agent/llm";
7	import { runImprovedPipeline } from "../../core/agent/improved-pipeline";
8	import type { CheckResult, IcpInput, PipelineResult } from "../../core/agent/types";
9	import { BudgetGuard, type BudgetSnapshot, type CompanyProvider } from "../../core/data/provider";
10	import { DEFAULT_RUN_CONFIG, type RunConfig, type Validation } from "../../core/types";
11	import {
12	  type SyntheticDependencies,
13	  runSyntheticPipeline,
14	  syntheticDependencies,
15	} from "../../app/results/_lib/synthetic-run";
16	import { hashCode, hashIp } from "./codes";
17	import type { LiveKeys } from "./config";
18	import { type CodeMode, type LiveStore, type RunOutcome } from "./store";
19	import { type ValidRequest, validateRequest } from "./validate";
20	
21	const IP_WINDOW_SECONDS = 60;
22	const IP_LIMIT = 20;
23	const BAD_CODE_WINDOW_SECONDS = 900;
24	const BAD_CODE_LIMIT = 5;
25	const RUN_LOCK_SECONDS = 330;
26	
27	export const LIVE_RUN_CONFIG: RunConfig = {
28	  ...DEFAULT_RUN_CONFIG,
29	  max_search_results: 10,
30	  max_enrichments: 5,
31	  model: "claude-haiku",
32	  max_llm_calls_per_run: 20,
33	  max_output_tokens_per_call: 1500,
34	};
35	
36	export const LIVE_SEARCH_SORT = { field: "crustdata_company_id", order: "asc" } as const;
37	
38	export const SYNTHETIC_NOTICES: readonly string[] = [
39	  "Synthetic demo: fixture companies and a fake model; your search criteria were not used.",
40	  "One outreach draft deliberately contains an injected unsupported number so you can see the claim check suppress it.",
41	];
42	
43	// ---- Response contract ----------------------------------------------------
44	
45	// What the injected mapper returns is opaque here. The mapper owns the shape
46	// of the results and must not copy upstream text into them.
47	export interface ResultsContext {
48	  readonly mode: CodeMode;
49	  readonly model: string;
50	}
51	
52	export type ToResults = (result: PipelineResult, ctx: ResultsContext) => unknown;
53	
54	export type LiveBody =
55	  | {
56	      readonly status: "ok";
57	      readonly mode: CodeMode;
58	      readonly results: unknown;
59	      readonly usage: {
60	        readonly runsRemaining: number;
61	        readonly searched: number;
62	        readonly enriched: number;
63	        readonly providerCostUsd: number;
64	      };
65	      readonly notices: readonly string[];
66	    }
67	  | { readonly status: "invalid_request"; readonly field: string; readonly message: string }
68	  | { readonly status: "rate_limited"; readonly retryAfterSeconds: number; readonly message: string }
69	  | { readonly status: "live_disabled"; readonly message: string }
70	  | { readonly status: "invalid_code"; readonly message: string }
71	  | { readonly status: "no_runs_left"; readonly message: string }
72	  | { readonly status: "run_in_progress"; readonly message: string }
73	  | { readonly status: "budget_exhausted"; readonly message: string }
74	  | { readonly status: "run_failed"; readonly message: string }
75	  | { readonly status: "live_unavailable"; readonly message: string };
76	
77	export interface LiveOutcome {
78	  readonly httpStatus: 200 | 400 | 401 | 403 | 409 | 429 | 502 | 503;
79	  readonly body: LiveBody;
80	}
81	
82	const MESSAGES = {
83	  live_disabled: "Live runs are switched off right now.",
84	  invalid_code: "That invite code is not valid.",
85	  no_runs_left: "This invite code has no runs left.",
86	  run_in_progress: "A run is already in progress for this code. Try again shortly.",
87	  budget_exhausted: "The data budget for live runs is used up. Please try again later.",
88	  run_failed: "The run failed. Please try again later.",
89	  live_unavailable: "Live mode is unavailable right now. Please try again later.",
90	  rate_limited: "Too many requests. Please wait before trying again.",
91	  industry_unmatched: "We could not match that industry. Try a broader term.",
92	} as const;
93	
94	const ISSUE_NOTICES: Readonly<Record<string, string | undefined>> = {
95	  enrich_partial: "Some companies could not be enriched, so those use basic search data only.",
96	  enrich_no_results: "No companies could be enriched, so results use basic search data only.",
97	  enrich_failed: "Enrichment failed, so results use basic search data only.",
98	  enrich_budget_exhausted: "The enrichment budget was reached before every company was enriched.",
99	  search_no_match: "No companies matched your criteria.",
100	  search_budget_exhausted: "The search budget was reached.",
101	  llm_call_cap_reached: "The model-call limit was reached, so some companies were not assessed.",
102	  llm_stopped: "Assessment stopped early after a model error, so some companies were not assessed.",
103	  llm_cost_incomplete: "Model cost for this run could not be fully measured.",
104	};
105	
106	const GENERIC_ISSUE_MESSAGE = "A step of the run reported a problem.";
107	
108	const FAILED_ASSESSMENT_MESSAGES: Readonly<Record<string, string | undefined>> = {
109	  llm_error: "The model could not assess this company.",
110	  malformed_output: "The model's answer could not be read.",
111	  truncated: "The model's answer was cut off.",
112	  invalid_assessment: "The model's assessment failed the checks.",
113	};
114	const GENERIC_ASSESSMENT_MESSAGE = "The assessment failed.";
115	
116	const VALIDATION_REASONS: Readonly<Record<string, string | undefined>> = {
117	  missing_name: "The company has no name.",
118	  missing_domain: "The company has no primary domain.",
119	  junk_website: "The website is not a company site.",
120	  duplicate_domain: "The company duplicates another result.",
121	  size_headcount_mismatch: "The size range and headcount disagree.",
122	  missing_linkedin: "The company has no LinkedIn page.",
123	};
124	const GENERIC_VALIDATION_REASON = "The company failed a data check.";
125	const GENERIC_FINDING_MESSAGE = "The assessment failed a check.";
126	const FINDING_MESSAGES: Readonly<Record<string, string | undefined>> = {
127	  fit_score_out_of_range: "The fit score is outside 0-100.",
128	  criterion_score_out_of_range: "A criterion score is outside 0-100.",
129	  missing_criterion: "A requested criterion was not scored.",
130	  unexpected_criterion: "A criterion was scored that was not requested.",
131	  duplicate_criterion: "A criterion was scored more than once.",
132	  unknown_fact_reference: "A score references an unknown fact.",
133	  uncertain_fact_reference: "A score references an uncertain fact.",
134	  no_citations: "The outreach cites no facts.",
135	  duplicate_citation: "The outreach cites a fact more than once.",
136	  unknown_citation: "The outreach cites an unknown fact.",
137	  model_fact_citation: "The outreach cites a model-written fact.",
138	  non_citeable_citation: "The outreach cites a fact that cannot be cited.",
139	  unsupported_number: "The outreach states a number no cited fact supports.",
140	};
141	
142	function scrubValidation(v: Validation | undefined): Validation | undefined {
143	  if (v === undefined) return v;
144	  return {
145	    ...v,
146	    issues: v.issues.map((i) => ({ ...i, reason: VALIDATION_REASONS[i.code] ?? GENERIC_VALIDATION_REASON })),
147	  };
148	}
149	
150	function scrubCheck(c: CheckResult): CheckResult {
151	  return {
152	    ...c,
153	    findings: c.findings.map(({ code, severity }) => ({
154	      code,
155	      severity,
156	      message: FINDING_MESSAGES[code] ?? GENERIC_FINDING_MESSAGE,
157	    })),
158	  };
159	}
160	
161	// Returns a copy of the pipeline result in which every free-text field that
162	// can carry upstream, model-error or user text is replaced by a fixed string
163	// chosen by its code or reason. Never mutates its input. Company data, facts
164	// and model assessments are the payload and pass through unchanged.
165	export function scrubResult(result: PipelineResult): PipelineResult {
166	  return {
167	    ...result,
168	    run: { ...result.run, input_description: "Run criteria withheld." },
169	    issues: result.issues.map((i) => ({ ...i, message: ISSUE_NOTICES[i.code] ?? GENERIC_ISSUE_MESSAGE })),
170	    prospects: result.prospects.map((p) => {
171	      const assessment =
172	        p.assessment.status === "failed"
173	          ? {
174	              ...p.assessment,
175	              message: FAILED_ASSESSMENT_MESSAGES[p.assessment.reason] ?? GENERIC_ASSESSMENT_MESSAGE,
176	            }
177	          : p.assessment;
178	      const scrubbed = { ...p, assessment };
179	      const search_validation = scrubValidation(p.search_validation);
180	      const validation = scrubValidation(p.validation);
181	      return {
182	        ...scrubbed,
183	        ...(search_validation !== undefined ? { search_validation } : {}),
184	        ...(validation !== undefined ? { validation } : {}),
185	        ...(p.checks !== undefined
186	          ? {
187	              checks: {
188	                ...p.checks,
189	                assessment: scrubCheck(p.checks.assessment),
190	                ...(p.checks.claims !== undefined ? { claims: scrubCheck(p.checks.claims) } : {}),
191	              },
192	            }
193	          : {}),
194	      };
195	    }),
196	  };
197	}
198	
199	function respond(httpStatus: LiveOutcome["httpStatus"], body: LiveBody): LiveOutcome {
200	  return { httpStatus, body };
201	}
202	
203	const simple = (
204	  httpStatus: LiveOutcome["httpStatus"],
205	  status:
206	    | "live_disabled"
207	    | "invalid_code"
208	    | "no_runs_left"
209	    | "run_in_progress"
210	    | "budget_exhausted"
211	    | "run_failed"
212	    | "live_unavailable",
213	): LiveOutcome => respond(httpStatus, { status, message: MESSAGES[status] });
214	
215	// For callers that fail before runLive (e.g. configuration is missing).
216	export const liveUnavailable = (): LiveOutcome => simple(503, "live_unavailable");
217	
218	function rateLimited(retryAfterSeconds: number): LiveOutcome {
219	  const seconds = Number.isFinite(retryAfterSeconds) ? Math.max(1, Math.ceil(retryAfterSeconds)) : 60;
220	  return respond(429, { status: "rate_limited", retryAfterSeconds: seconds, message: MESSAGES.rate_limited });
221	}
222	
223	function noticesFromIssues(issues: readonly { readonly code: string }[]): string[] {
224	  const out: string[] = [];
225	  for (const issue of issues) {
226	    const text = ISSUE_NOTICES[issue.code];
227	    if (text !== undefined && !out.includes(text)) out.push(text);
228	  }
229	  return out;
230	}
231	
232	// ---- Dependencies -----------------------------------------------------------
233	
234	export interface LiveProviderBundle {
235	  readonly provider: CompanyProvider;
236	  readonly budget: { snapshot(): BudgetSnapshot };
237	}
238	
239	export interface LiveDeps {
240	  readonly store: LiveStore;
241	  readonly hmacSecret: string;
242	  // null when live keys are not configured: synthetic codes still run.
243	  readonly live: LiveKeys | null;
244	  readonly now: () => Date;
245	  // Live factories. Never called in synthetic mode.
246	  readonly createProvider: (keys: LiveKeys, config: RunConfig) => LiveProviderBundle | Promise<LiveProviderBundle>;
247	  readonly createLlm: (keys: LiveKeys) => LlmClient | Promise<LlmClient>;
248	  readonly synthetic?: SyntheticDependencies;
249	  // Builds the 200 body's results for both modes.
250	  readonly toResults: ToResults;
251	}
252	
253	// The real factories. SDKs are imported lazily so synthetic runs and unit
254	// tests never load them.
255	export const realFactories: Pick<LiveDeps, "createProvider" | "createLlm"> = {
256	  async createProvider(keys, config) {
257	    const { CrustdataProvider } = await import("../../core/data/crustdata-provider");
258	    const budget = new BudgetGuard(config);
259	    const provider = new CrustdataProvider({
260	      api_key: keys.crustdataApiKey,
261	      budget,
262	      search_sort: LIVE_SEARCH_SORT,
263	    });
264	    return { provider, budget };
265	  },
266	  async createLlm(keys) {
267	    const { createGatewayLlmClient } = await import("../../core/agent/gateway-client");
268	    return createGatewayLlmClient({ apiKey: keys.llmApiKey, baseURL: keys.llmBaseUrl });
269	  },
270	};
271	
272	// ---- Orchestration ----------------------------------------------------------
273	
274	export async function runLive(
275	  request: { readonly code: unknown; readonly icp: unknown },
276	  ip: string,
277	  deps: LiveDeps,
278	): Promise<LiveOutcome> {
279	  const checked = validateRequest(request);
280	  if (!checked.ok) {
281	    return respond(400, { status: "invalid_request", field: checked.field, message: checked.message });
282	  }
283	  const valid = checked.value;
284	
285	  let reserved: Reserved;
286	  try {
287	    const { store, hmacSecret } = deps;
288	    const ipHash = hashIp(ip, hmacSecret);
289	
290	    const rate = await store.hit(`ip:${ipHash}`, deps.now(), IP_WINDOW_SECONDS, IP_LIMIT);
291	    if (!rate.allowed) return rateLimited(rate.retryAfterSeconds);
292	
293	    const result = await store.reserveRun(hashCode(valid.code, hmacSecret), deps.now(), RUN_LOCK_SECONDS);
294	    if (!result.ok) {
295	      switch (result.reason) {
296	        case "invalid_code":
297	        case "disabled": {
298	          const bad = await store.hit(`badcode:${ipHash}`, deps.now(), BAD_CODE_WINDOW_SECONDS, BAD_CODE_LIMIT);
299	          if (!bad.allowed) return rateLimited(bad.retryAfterSeconds);
300	          return simple(401, "invalid_code");
301	        }
302	        case "no_runs_left":
303	          return simple(403, "no_runs_left");
304	        case "run_in_progress":
305	          return simple(409, "run_in_progress");
306	        default:
307	          return simple(503, "live_unavailable");
308	      }
309	    }
310	    reserved = { runId: result.runId, runsRemaining: result.runsRemaining, mode: result.mode };
311	  } catch {
312	    return simple(503, "live_unavailable");
313	  }
314	
315	  // From here a run exists: every exit must finish or release it.
316	  const { store } = deps;
317	
318	  // The kill switch only stops live-mode codes; synthetic codes never read it.
319	  if (reserved.mode === "live") {
320	    let enabled: boolean;
321	    try {
322	      enabled = await store.isLiveEnabled();
323	    } catch {
324	      await giveBack(store, reserved.runId);
325	      return simple(503, "live_unavailable");
326	    }
327	    if (!enabled) {
328	      await giveBack(store, reserved.runId);
329	      return simple(503, "live_disabled");
330	    }
331	  }
332	
333	  const settle = async (op: () => Promise<void>) => {
334	    try {
335	      await op();
336	    } catch {
337	      // The outcome is already decided; a store failure cannot change it.
338	    }
339	  };
340	  const failed = async (outcome: Partial<RunOutcome> = {}): Promise<LiveOutcome> => {
341	    await settle(() =>
342	      store.finishRun(reserved.runId, {
343	        status: "failed",
344	        searched: 0,
345	        enriched: 0,
346	        providerCostUsd: 0,
347	        modelCostUsd: 0,
348	        errorCategory: "run_failed",
349	        ...outcome,
350	      }),
351	    );
352	    return simple(502, "run_failed");
353	  };
354	
355	  try {
356	    return reserved.mode === "synthetic"
357	      ? await runSynthetic(reserved, deps, failed)
358	      : await runLiveMode(valid, reserved, deps, failed);
359	  } catch {
360	    return failed();
361	  }
362	}
363	
364	async function giveBack(store: LiveStore, runId: string): Promise<void> {
365	  try {
366	    await store.releaseRun(runId);
367	  } catch {
368	    // Nothing more can be done; the lock expires on its own.
369	  }
370	}
371	
372	// The user already has what the run produced, so a bookkeeping failure is
373	// retried once and then ignored. It is never recorded as a different status.
374	async function finishCompleted(store: LiveStore, runId: string, outcome: RunOutcome): Promise<void> {
375	  for (let attempt = 0; attempt < 2; attempt++) {
376	    try {
377	      await store.finishRun(runId, outcome);
378	      return;
379	    } catch {
380	      // Retry once, then give up.
381	    }
382	  }
383	}
384	
385	interface Reserved {
386	  readonly runId: string;
387	  readonly runsRemaining: number;
388	  readonly mode: CodeMode;
389	}
390	
391	type Failed = (outcome?: Partial<RunOutcome>) => Promise<LiveOutcome>;
392	
393	async function runSynthetic(reserved: Reserved, deps: LiveDeps, failed: Failed): Promise<LiveOutcome> {
394	  const run = await runSyntheticPipeline("synthetic", deps.synthetic ?? syntheticDependencies);
395	  if (run.kind !== "ok") return failed();
396	  const { result } = run;
397	  const searched = result.usage.provider.searched;
398	  const enriched = result.usage.provider.enriched;
399	  const results = deps.toResults(scrubResult(result), { mode: "synthetic", model: "fake" });
400	  await finishCompleted(deps.store, reserved.runId, {
401	    status: "completed",
402	    searched,
403	    enriched,
404	    providerCostUsd: 0,
405	    modelCostUsd: 0,
406	  });
407	  const notices = [...SYNTHETIC_NOTICES, ...noticesFromIssues(result.issues)];
408	  return respond(200, {
409	    status: "ok",
410	    mode: "synthetic",
411	    results,
412	    usage: { runsRemaining: reserved.runsRemaining, searched, enriched, providerCostUsd: 0 },
413	    notices,
414	  });
415	}
416	
417	async function runLiveMode(
418	  valid: ValidRequest,
419	  reserved: Reserved,
420	  deps: LiveDeps,
421	  failed: Failed,
422	): Promise<LiveOutcome> {
423	  const { store } = deps;
424	  const release = async (): Promise<LiveOutcome> => {
425	    await giveBack(store, reserved.runId);
426	    return simple(502, "run_failed");
427	  };
428	
429	  // Before the first paid call: any failure gives the run back.
430	  let bundle: LiveProviderBundle;
431	  let llm: LlmClient;
432	  let industry: string;
433	  const notices: string[] = [];
434	  try {
435	    if (deps.live === null) return await release();
436	    bundle = await deps.createProvider(deps.live, LIVE_RUN_CONFIG);
437	    llm = await deps.createLlm(deps.live);
438	
439	    const suggestions = await bundle.provider.autocompleteIndustry(valid.icp.industry);
440	    if (!suggestions.ok && suggestions.error.category === "no_match") {
441	      await store.releaseRun(reserved.runId);
442	      return respond(400, {
443	        status: "invalid_request",
444	        field: "industry",
445	        message: MESSAGES.industry_unmatched,
446	      });
447	    }
448	    if (!suggestions.ok || suggestions.data.length === 0) return await release();
449	    industry = suggestions.data[0];
450	    notices.push(`Searched the industry "${industry.slice(0, 80)}", the closest match to what you entered.`);
451	  } catch {
452	    return release();
453	  }
454	
455	  const icp: IcpInput = {
456	    industry,
457	    employee_count_ranges: valid.icp.sizes,
458	    locations: [valid.icp.country],
459	    keywords: [],
460	    excluded_domains: [],
461	  };
462	
463	  let result: PipelineResult;
464	  try {
465	    result = await runImprovedPipeline(
466	      icp,
467	      { provider: bundle.provider, budget: bundle.budget, llm, fact_provider: "crustdata" },
468	      { config: LIVE_RUN_CONFIG },
469	    );
470	  } catch {
471	    const snap = safeSnapshot(bundle.budget);
472	    return failed({
473	      searched: snap.searched,
474	      enriched: snap.enriched,
475	      providerCostUsd: snap.cost_usd,
476	      errorCategory: "pipeline_exception",
477	    });
478	  }
479	
480	  const searched = result.usage.provider.searched;
481	  const enriched = result.usage.provider.enriched;
482	  const providerCostUsd = result.usage.provider.cost_usd;
483	  const modelCostUsd = result.usage.llm_cost.known_usd;
484	
485	  if (result.status === "stopped") {
486	    const exhausted = result.issues.some((i) => i.error_category === "budget_cap_reached");
487	    const outcome: RunOutcome = {
488	      status: exhausted ? "budget_exhausted" : "failed",
489	      searched,
490	      enriched,
491	      providerCostUsd,
492	      modelCostUsd,
493	      errorCategory: exhausted ? "budget_cap_reached" : "pipeline_stopped",
494	    };
495	    try {
496	      await store.finishRun(reserved.runId, outcome);
497	    } catch {
498	      // The response is already decided.
499	    }
500	    return simple(exhausted ? 503 : 502, exhausted ? "budget_exhausted" : "run_failed");
501	  }
502	
503	  let results: unknown;
504	  try {
505	    results = deps.toResults(scrubResult(result), { mode: "live", model: LIVE_RUN_CONFIG.model });
506	  } catch {
507	    return failed({ searched, enriched, providerCostUsd, modelCostUsd, errorCategory: "results_mapping" });
508	  }
509	
510	  await finishCompleted(store, reserved.runId, {
511	    status: "completed",
512	    searched,
513	    enriched,
514	    providerCostUsd,
515	    modelCostUsd,
516	  });
517	  return respond(200, {
518	    status: "ok",
519	    mode: "live",
520	    results,
521	    usage: { runsRemaining: reserved.runsRemaining, searched, enriched, providerCostUsd },
522	    notices: [...notices, ...noticesFromIssues(result.issues)],
523	  });
524	}
525	
526	function safeSnapshot(budget: { snapshot(): BudgetSnapshot }): BudgetSnapshot {
527	  try {
528	    return budget.snapshot();
529	  } catch {
530	    return { cost_usd: 0, searched: 0, enriched: 0 };
531	  }
532	}
533

